code:
def solve(word1: str, word2: str) -> int:
    """Compute the Levenshtein edit distance between two strings.
    Operations allowed: insertion, deletion, substitution, each cost 1.
    Returns the minimum number of operations required to convert word1 into word2.
    """
    m, n = len(word1), len(word2)
    # dp[i][j] = distance between word1[:i] and word2[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i  # delete all i chars
    for j in range(n + 1):
        dp[0][j] = j  # insert all j chars
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],      # deletion
                    dp[i][j - 1],      # insertion
                    dp[i - 1][j - 1]   # substitution
                )
    return dp[m][n]

