    n = len(res)
    i = n - 2
    while i >= 0 and res[i] >= res[i + 1]:
        i -= 1
    if i >= 0:
        j = n - 1
        while res[j] <= res[i]:
            j -= 1
        res[i], res[j] = res[j], res[i]
    else:
        return sorted(res)
    res[i + 1:] = reversed(res[i + 1:])
    return res

