def solve(nums):
    """Return length of longest non‑decreasing subsequence.
    Uses patience sorting with bisect_right so equal elements can extend the subsequence.
    """
    import bisect
    tails = []
    for x in nums:
        i = bisect.bisect_right(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

